function a(e){if(e?.subtype!=="Widget")return!1;switch(e.fieldType){case"Tx":case"Ch":return!0;case"Btn":return!e.pushButton;default:return!1}}async function n(e,t){return e?(await(await e.getPage(t)).getAnnotations({intent:"display"})).filter(r=>r?.subtype==="Widget"):[]}async function s(e,t){return(await n(e,t)).some(a)}async function u(e,t){return(await n(e,t)).length>0}export{s as heeftBewerkbareVelden,u as heeftVeldWidgets,a as isBewerkbaarVeld};
